#include <iostream>
#include <stdexcept>
#include <string>

// Custom exception class representing divide-by-zero error
class DivideByZeroException : public std::runtime_error {
public:
    DivideByZeroException()
        : std::runtime_error("attempted to divide by zero") {}
};

// Perform division; throws DivideByZeroException if denominator is 0
double quotient(int numerator, int denominator) {
    if (denominator == 0) {
        throw DivideByZeroException();
    }
    return static_cast<double>(numerator) / denominator;
}

int main() {
    int num1 = 0;
    int num2 = 0;

    // Read integer pairs from stdin
    while (std::cin >> num1 >> num2) {
        try {
            double result = quotient(num1, num2);
            std::cout << "The quotient is: " << result << "\n";
        } catch (const DivideByZeroException& ex) {
            std::cout << "Exception occurred: " << ex.what() << "\n";
        }
    }
    return 0;
}
